import org.apache.commons.lang3.math.NumberUtils;
import java.math.BigDecimal;
import java.math.RoundingMode;

public class Probe {
    public static void main(String[] args) throws Exception {
        p("2.5");
        p("123.45");
        p("2.5e0");
        p("1.0f");
        p("1.0d");
        p("-0x1A");
        p("0x1AL");
        p("10l");
        p("0xCAFEBABE");
        p("0xFFFFFFFFL");
        p("010");
        p("1.2.3");
        System.out.println("isCreatable 09 -> " + NumberUtils.isCreatable("09"));
        System.out.println("isCreatable 0.1 -> " + NumberUtils.isCreatable("0.1"));
        System.out.println("isParsable 09 -> " + NumberUtils.isParsable("09"));
        System.out.println("toScaledBigDecimal null -> " + NumberUtils.toScaledBigDecimal((BigDecimal) null));
        System.out.println("toScaledBigDecimal 2.255 -> " + NumberUtils.toScaledBigDecimal(BigDecimal.valueOf(2.255), 2, RoundingMode.HALF_EVEN));
    }

    static void p(String s) {
        try {
            Object n = NumberUtils.createNumber(s);
            System.out.println(s + " -> " + n.getClass().getSimpleName() + " : " + n);
        } catch (Exception e) {
            System.out.println(s + " -> EXC " + e);
        }
    }
}
